import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Crimson/Seastore Meeting 2022-11-30","description":"","frontmatter":{"title":"Ceph Crimson/Seastore Meeting 2022-11-30","date":"2022-11-30T00:00:00.000Z","updated":"2022-12-03T00:00:00.000Z","tags":["Ceph","代码审查","性能优化","分布式存储","功能实现"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Crimson_Seastore_Meeting_2022-11-30.md","filePath":"posts/2022/Ceph_Crimson_Seastore_Meeting_2022-11-30.md","lastUpdated":1780460162000}'),o={name:"posts/2022/Ceph_Crimson_Seastore_Meeting_2022-11-30.md"};function r(s,e,n,h,u,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了Ceph存储系统的开发进展和相关技术问题，包括性能优化、代码审查、功能实现等方面。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>代码审查和功能迁移</strong></p><ul><li>上周主要进行了代码审查工作。</li><li>计划迁移Oh Map功能，并推进Split Protocol V2 Messenger和Handshake的开发。</li><li>讨论了在对象存储接口添加注释的必要性。</li></ul></li><li><p><strong>性能回归问题</strong></p><ul><li>发现共享存储支持下的性能有所下降，目前正在解决这一问题。</li><li>通过添加Mall客户端进行测试，以验证性能改进。</li></ul></li><li><p><strong>代码调试和单元测试</strong></p><ul><li>正在调试Picture Remove代码，已接近完成，计划添加单元测试并准备PR（Pull Request）进行审查。</li></ul></li><li><p><strong>缓存数据提升功能</strong></p><ul><li>讨论了实现缓存数据提升功能的必要性和可行性。</li><li>该功能旨在将频繁访问的数据从冷存储提升到热存储，以优化内存使用效率。</li><li>讨论了该功能对最终性能的贡献和引入的复杂性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续推进Split Protocol V2 Messenger和Handshake的开发。</li><li>解决共享存储支持下的性能回归问题。</li><li>完成Picture Remove代码的调试和单元测试，并提交PR进行审查。</li><li>探讨并实现缓存数据提升功能，评估其对性能的影响，并考虑架构上的调整。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成Oh Map功能的迁移工作。</li><li>继续解决性能回归问题，并进行相关测试。</li><li>完成Picture Remove代码的单元测试，并提交PR。</li><li>进一步讨论和实现缓存数据提升功能，评估其对性能的影响，并考虑架构上的调整。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议结束时，与会者互相祝愿一周愉快。</li></ul><h3 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h3><ul><li>Ceph</li><li>Split Protocol V2</li><li>Oh Map</li><li>Performance Regression</li><li>Blue Store</li><li>Object Store Interface</li><li>Cache Data Promote</li><li>Memory Constrained Devices</li></ul><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>会议顺利结束，各项议题和后续行动计划已明确，期待各团队成员的进一步进展和合作。</p>',15)])])}const _=l(o,[["render",r]]);export{c as __pageData,_ as default};
